import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 130 He can't have been ... He must have been ...","description":"学习 情态动词 + have done，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 130 He can't have been ... He must have been ...","description":"学习 情态动词 + have done，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 情态动词 + have done，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 129 Seventy miles an hour","link":"/life/english/new-concept/book-1/unit-06/lesson-129"},"next":{"text":"第一册：英语初阶 · Lesson 131 Don't be so sure!","link":"/life/english/new-concept/book-1/unit-06/lesson-131"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 129 Seventy miles an hour","link":"/life/english/new-concept/book-1/unit-06/lesson-129"},"next":{"text":"第一册：英语初阶 · Lesson 131 Don't be so sure!","link":"/life/english/new-concept/book-1/unit-06/lesson-131"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-130.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-130.md"}`),i={name:"life/english/new-concept/book-1/unit-06/lesson-130.md"};function s(r,e,l,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-130-he-can-t-have-been-he-must-have-been" tabindex="-1">第一册：英语初阶 · Lesson 130 He can&#39;t have been ... He must have been ... <a class="header-anchor" href="#第一册-英语初阶-·-lesson-130-he-can-t-have-been-he-must-have-been" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 130 He can&#39;t have been ... He must have been ...&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-129">配套课 Lesson 129</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>根据现在的证据推测过去 本课要掌握情态动词 + have done，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>speed</td><td>/spiːd/</td><td>n.</td><td>速度</td><td>at high speed</td></tr><tr><td>mile</td><td>/maɪl/</td><td>n.</td><td>英里</td><td>miles an hour</td></tr><tr><td>limit</td><td>/ˈlɪmɪt/</td><td>n.</td><td>限制</td><td>a speed limit</td></tr><tr><td>sign</td><td>/saɪn/</td><td>n.</td><td>标志</td><td>a road sign</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>must have missed — 推测过去一定错过</li><li>cannot have seen — 推测过去不可能看见</li></ul><h2 id="语法讲解-情态动词-have-done" tabindex="-1">语法讲解：情态动词 + have done <a class="header-anchor" href="#语法讲解-情态动词-have-done" aria-label="Permalink to &quot;语法讲解：情态动词 + have done&quot;">​</a></h2><p>must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>He cannot have read the sign; it was covered.</p></blockquote><p>他不可能读到标志，它被遮住了。</p><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>must have rained 是推测，不能写 must had rained；情态动词后保留 have 原形。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“He cannot have read the sign; it was covered.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>He cannot have read the sign; it was covered. The road is wet; it must have rained overnight.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“根据现在的证据推测过去”写两至三句，再读给同伴听。至少使用一次情态动词 + have done，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。 The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 have/had：He cannot ___ read the sign.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> have</p><p><strong>解析：</strong> 按本课规则判断：must have + 过去分词表示对过去的强推断，can&#39;t have + 过去分词表示认为过去不可能发生。它们不是现在完成时的普通肯否定，而是情态推断结构。过去状态用 have been，过去动作使用相应分词。速度等信息应作为证据，不要把猜测说成亲眼观察；本页只练语言，不判断实际交通责任。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“他不可能读到标志，它被遮住了。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He cannot have read the sign; it was covered.</p><p><strong>解析：</strong> Cannot have read 对过去是否读到标志作否定推断；it was covered 给出证据，但推断本身不是亲眼观察。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The road is wet; it must have rained overnight.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 路是湿的，夜里一定下过雨。</p><p><strong>解析：</strong> The road is wet 是现在证据；must have rained 对过去下雨作推断，overnight 指夜里。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：情态动词 + have done。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-129">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-131">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",s]]);export{p as __pageData,b as default};
